import tarfile


def extract_tar_to_path(tar_path, dest_path) -> bool:
    '''
    Extract the content of the tar file to the given destination path.
    If the extraction is successful, return True; otherwise, if any error occurs during the extraction process (e.g. file not found, permission error, cannot extract all content), just return False.

    Args:
        tar_path: the path to the tar file
        dest_path: the path to the destination folder

    Returns:
        True if the extraction is successful; otherwise, False
    '''
    import os

    def _is_within(base, target):
        try:
            return os.path.commonpath([base, target]) == base
        except ValueError:
            return False

    try:
        dest_real = os.path.realpath(os.path.abspath(dest_path))

        with tarfile.open(tar_path, 'r') as tar:
            members = tar.getmembers()

            # Validate every member before extracting anything.
            for member in members:
                name = member.name
                if not name or '\x00' in name:
                    return False
                if os.path.isabs(name) or name.startswith(('/', '\\')):
                    return False
                drive, _ = os.path.splitdrive(name)
                if drive:
                    return False

                target = os.path.realpath(os.path.join(dest_real, name))
                if not _is_within(dest_real, target):
                    return False

                # Reject device files, FIFOs and other special entries.
                if not (member.isfile() or member.isdir() or
                        member.issym() or member.islnk()):
                    return False

                if member.issym():
                    linkname = member.linkname
                    if not linkname or os.path.isabs(linkname):
                        return False
                    link_target = os.path.realpath(
                        os.path.join(os.path.dirname(target), linkname))
                    if not _is_within(dest_real, link_target):
                        return False
                elif member.islnk():
                    linkname = member.linkname
                    if not linkname or os.path.isabs(linkname):
                        return False
                    link_target = os.path.realpath(
                        os.path.join(dest_real, linkname))
                    if not _is_within(dest_real, link_target):
                        return False

            # Extract, using the built-in safety filter when available.
            if hasattr(tarfile, 'data_filter'):
                tar.extractall(dest_real, members=members, filter='data')
            else:
                for member in members:
                    # Strip dangerous permission bits and ownership info.
                    if member.isfile() or member.isdir():
                        member.mode &= 0o755
                    tar.extract(member, dest_real, set_attrs=False)
    except Exception:
        return False
    return True
